CREATE TYPE "RoleName" AS ENUM ('ADMIN', 'MEMBER');
CREATE TYPE "AuditAction" AS ENUM ('USER_CREATED','USER_UPDATED','USER_DEACTIVATED','RESPONSIBILITY_CREATED','RESPONSIBILITY_UPDATED','RESPONSIBILITY_ASSIGNED','RESPONSIBILITY_UNASSIGNED','EXPENSE_CREATED','EXPENSE_UPDATED','EXPENSE_DELETED','PROFILE_UPDATED','PASSWORD_CHANGED');
CREATE TABLE "Role" ("id" TEXT PRIMARY KEY,"name" "RoleName" NOT NULL UNIQUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"firstName" TEXT NOT NULL,"lastName" TEXT NOT NULL,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"profileImageUrl" TEXT,"roleId" TEXT NOT NULL,"isActive" BOOLEAN NOT NULL DEFAULT true,"lastLoginAt" TIMESTAMP(3),"passwordResetTokenHash" TEXT,"passwordResetExpiresAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "User_roleId_fkey" FOREIGN KEY ("roleId") REFERENCES "Role"("id"));
CREATE TABLE "Responsibility" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL UNIQUE,"description" TEXT,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "ResponsibilitySubItem" ("id" TEXT PRIMARY KEY,"responsibilityId" TEXT NOT NULL,"name" TEXT NOT NULL,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ResponsibilitySubItem_responsibilityId_fkey" FOREIGN KEY ("responsibilityId") REFERENCES "Responsibility"("id") ON DELETE CASCADE,UNIQUE("responsibilityId","name"));
CREATE TABLE "UserResponsibility" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"responsibilityId" TEXT NOT NULL,"assignedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"assignedById" TEXT,CONSTRAINT "UserResponsibility_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE,CONSTRAINT "UserResponsibility_responsibilityId_fkey" FOREIGN KEY ("responsibilityId") REFERENCES "Responsibility"("id") ON DELETE CASCADE,UNIQUE("userId","responsibilityId"));
CREATE TABLE "Expense" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"responsibilityId" TEXT NOT NULL,"subItemId" TEXT,"expenseDate" DATE NOT NULL,"amount" DECIMAL(12,2) NOT NULL,"remark" TEXT,"createdById" TEXT NOT NULL,"updatedById" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Expense_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id"),CONSTRAINT "Expense_responsibilityId_fkey" FOREIGN KEY ("responsibilityId") REFERENCES "Responsibility"("id"),CONSTRAINT "Expense_subItemId_fkey" FOREIGN KEY ("subItemId") REFERENCES "ResponsibilitySubItem"("id"),CONSTRAINT "Expense_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id"),CONSTRAINT "Expense_updatedById_fkey" FOREIGN KEY ("updatedById") REFERENCES "User"("id"));
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY,"actorUserId" TEXT,"action" "AuditAction" NOT NULL,"entityType" TEXT NOT NULL,"entityId" TEXT NOT NULL,"details" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditLog_actorUserId_fkey" FOREIGN KEY ("actorUserId") REFERENCES "User"("id") ON DELETE SET NULL);
CREATE INDEX "Expense_userId_expenseDate_idx" ON "Expense"("userId","expenseDate"); CREATE INDEX "Expense_responsibilityId_expenseDate_idx" ON "Expense"("responsibilityId","expenseDate"); CREATE INDEX "Expense_expenseDate_idx" ON "Expense"("expenseDate"); CREATE INDEX "UserResponsibility_responsibilityId_idx" ON "UserResponsibility"("responsibilityId"); CREATE INDEX "AuditLog_createdAt_idx" ON "AuditLog"("createdAt"); CREATE INDEX "AuditLog_entityType_entityId_idx" ON "AuditLog"("entityType","entityId");
